CREATE TABLE IF NOT EXISTS telemetry_meta.source_mapping (mapping_version UInt32, policy_version UInt32, collector_id String, trust_domain String, deployment_id String, provider_id String, instance_id String, tenant_id String, project_id String, environment LowCardinality(String), source_product String, projection_route_ids Array(String), status LowCardinality(String), valid_from DateTime64(3,'UTC'), valid_to Nullable(DateTime64(3,'UTC')), created_at DateTime64(3,'UTC') DEFAULT now64(3)) ENGINE=ReplacingMergeTree(created_at) ORDER BY (collector_id,deployment_id,provider_id,instance_id,mapping_version);
CREATE TABLE IF NOT EXISTS telemetry_meta.schema_definition (schema_name String,schema_version String,compatibility_mode LowCardinality(String),status LowCardinality(String),schema_hash FixedString(64),json_schema String,valid_from DateTime64(3,'UTC'),valid_to Nullable(DateTime64(3,'UTC')),created_at DateTime64(3,'UTC') DEFAULT now64(3)) ENGINE=ReplacingMergeTree(created_at) ORDER BY (schema_name,schema_version);
CREATE TABLE IF NOT EXISTS telemetry_meta.normalizer_definition (normalizer_id String,normalizer_version UInt32,source_system LowCardinality(String),source_schema_name String,source_schema_range String,target_envelope_version String,status LowCardinality(String),created_at DateTime64(3,'UTC') DEFAULT now64(3)) ENGINE=ReplacingMergeTree(created_at) ORDER BY (normalizer_id,normalizer_version);
CREATE TABLE IF NOT EXISTS telemetry_meta.projection_definition (projection_id String,projection_version UInt32,accepted_fact_types Array(String),target_models Array(String),status LowCardinality(String),created_at DateTime64(3,'UTC') DEFAULT now64(3)) ENGINE=ReplacingMergeTree(created_at) ORDER BY (projection_id,projection_version);
CREATE TABLE IF NOT EXISTS telemetry_meta.projection_target (target_id String,target_type LowCardinality(String),endpoint_ref String,database_mapping_json String,write_mode LowCardinality(String),status LowCardinality(String),valid_from DateTime64(3,'UTC'),valid_to Nullable(DateTime64(3,'UTC')),created_at DateTime64(3,'UTC') DEFAULT now64(3)) ENGINE=ReplacingMergeTree(created_at) ORDER BY target_id;
CREATE TABLE IF NOT EXISTS telemetry_meta.projection_route (route_id String,source_system LowCardinality(String),fact_type String,tenant_scope String,project_scope String,relation_selector String,target_id String,fanout_mode LowCardinality(String),projection_set Array(String),valid_from DateTime64(3,'UTC'),valid_to Nullable(DateTime64(3,'UTC')),created_at DateTime64(3,'UTC') DEFAULT now64(3)) ENGINE=ReplacingMergeTree(created_at) ORDER BY (route_id,target_id);
CREATE TABLE IF NOT EXISTS telemetry_meta.projection_checkpoint (target_id String,checkpoint_name String,wal_segment UInt64,wal_offset UInt64,updated_at DateTime64(3,'UTC')) ENGINE=ReplacingMergeTree(updated_at) ORDER BY (target_id,checkpoint_name);
CREATE TABLE IF NOT EXISTS telemetry_meta.projection_dead_letter (dlq_id UUID,target_id String,fact_id Nullable(UUID),source_record_id String,error_code String,error_summary String,payload_summary String,created_at DateTime64(3,'UTC'),resolved_at Nullable(DateTime64(3,'UTC'))) ENGINE=MergeTree PARTITION BY toYYYYMM(created_at) ORDER BY (target_id,created_at,dlq_id);
CREATE TABLE IF NOT EXISTS telemetry_meta.replay_job (job_id UUID,scope_json String,normalizer_version UInt32,projection_id String,projection_version UInt32,target_ids Array(String),status LowCardinality(String),created_at DateTime64(3,'UTC'),started_at Nullable(DateTime64(3,'UTC')),completed_at Nullable(DateTime64(3,'UTC')),result_json String) ENGINE=ReplacingMergeTree(created_at) ORDER BY job_id;
